/* Radar Seguro RJ PRO — badge V232 */(()=>{'use strict';function add(){if(document.getElementById('radar-version-v232'))return true;const p=[...document.querySelectorAll('button')].find(x=>/postos/i.test(x.textContent||''));if(!p)return false;const b=document.createElement('div');b.id='radar-version-v232';b.textContent='V 232';Object.assign(b.style,{position:'fixed',zIndex:99999,background:'rgba(8,18,28,.9)',color:'#fff',font:'700 14px Arial',padding:'5px 12px',borderRadius:'14px',pointerEvents:'none'});document.body.appendChild(b);const f=()=>{const r=p.getBoundingClientRect();b.style.left=Math.round(r.left+r.width/2-b.offsetWidth/2)+'px';b.style.top=Math.round(r.bottom+8)+'px'};f();addEventListener('resize',f);return true}let n=0,t=setInterval(()=>{if(add()||++n>200)clearInterval(t)},100)})();